package main
import "fmt"
func unique(items []string) []string {
seen := make(map[string]bool)
result := []string{}
for _, item := range items {
if !seen[item] { seen[item] = true; result = append(result, item) }
}
return result
}
func main() { fmt.Println(unique([]string{"go", "rust", "go", "python"})) }

