	"fmt"
	"sync"
)

func main() {
	var group sync.WaitGroup
	var mutex sync.Mutex
	count := 0
	for worker := 0; worker < 3; worker++ {
		group.Add(1)
		go func() {
			defer group.Done()
			mutex.Lock()
			count++
			mutex.Unlock()
		}()
	}
	group.Wait()
	fmt.Println("completed:", count)
}

