package main

import "testing"

func Add(left, right int) int { return left + right }

func TestAdd(t *testing.T) {
	cases := []struct { name string; left, right, want int }{
		{"positive", 2, 3, 5},
		{"negative", -2, -3, -5},
		{"zero", 0, 0, 0},
	}
	for _, testCase := range cases {
		t.Run(testCase.name, func(t *testing.T) {
			if got := Add(testCase.left, testCase.right); got != testCase.want {
				t.Fatalf("got %d, want %d", got, testCase.want)
			}
		})
	}
}

